import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.D2cFUyj2.js";var c=JSON.parse(`{"title":"System Architecture","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Three-Process Isolation Model","slug":"_1-three-process-isolation-model","link":"#_1-three-process-isolation-model","children":[{"level":3,"title":"1. Background Indexing Service (Lertaro.Service.exe)","slug":"_1-background-indexing-service-lertaro-service-exe","link":"#_1-background-indexing-service-lertaro-service-exe","children":[]},{"level":3,"title":"2. User Interaction Application (Lertaro.App)","slug":"_2-user-interaction-application-lertaro-app","link":"#_2-user-interaction-application-lertaro-app","children":[]},{"level":3,"title":"3. Global Keyboard Hook & Window Adapter Process (Lertaro.Service --hook)","slug":"_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook","link":"#_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook","children":[]}]},{"level":2,"title":"2. Shared Core Library (Lertaro.Core)","slug":"_2-shared-core-library-lertaro-core","link":"#_2-shared-core-library-lertaro-core","children":[]},{"level":2,"title":"3. Plugin Architecture & Lifecycle","slug":"_3-plugin-architecture-lifecycle","link":"#_3-plugin-architecture-lifecycle","children":[]}],"relativePath":"dev-guide/architecture.md","filePath":"dev-guide/architecture.md","lastUpdated":1791468491000}`),l={name:`dev-guide/architecture.md`};function u(i,c,l,u,d,f){let p=s(`ArchitectureDiagram`);return e(),o(`div`,null,[c[0]||=n(`h1`,{id:`system-architecture`,tabindex:`-1`},[t(`System Architecture `),n(`a`,{class:`header-anchor`,href:`#system-architecture`,"aria-label":`Permalink to “System Architecture”`},`​`)],-1),c[1]||=n(`p`,null,`Lertaro is built upon a multi-process isolation model and a layered architecture, delivering sub-millisecond retrieval and desktop integration while keeping the system stable and secure.`,-1),a(p),c[2]||=r(`<h2 id="_1-three-process-isolation-model" tabindex="-1">1. Three-Process Isolation Model <a class="header-anchor" href="#_1-three-process-isolation-model" aria-label="Permalink to “1. Three-Process Isolation Model”">​</a></h2><p>To prevent single component failures from crashing the entire system and to minimize elevated Windows privileges, Lertaro&#39;s runtime is decoupled into three independent processes:</p><h3 id="_1-background-indexing-service-lertaro-service-exe" tabindex="-1">1. Background Indexing Service (<code>Lertaro.Service.exe</code>) <a class="header-anchor" href="#_1-background-indexing-service-lertaro-service-exe" aria-label="Permalink to “1. Background Indexing Service (Lertaro.Service.exe)”">​</a></h3><ul><li><strong>Identity</strong>: Runs continuously as a Windows Service under the <code>LocalSystem</code> account.</li><li><strong>Responsibilities</strong>: Performs disk indexing and change tracking. Reads NTFS / ReFS USN Change Journals and $MFT tables; listens to FAT32 / exFAT change events; periodically crawls and caches SMB / NAS network shares.</li><li><strong>Security &amp; Performance</strong>: Running at the SYSTEM level allows raw disk volume metadata access without prompting UAC dialogs, returning results to the user-mode App over high-speed named pipes while keeping the UI unprivileged.</li></ul><h3 id="_2-user-interaction-application-lertaro-app" tabindex="-1">2. User Interaction Application (<code>Lertaro.App</code>) <a class="header-anchor" href="#_2-user-interaction-application-lertaro-app" aria-label="Permalink to “2. User Interaction Application (Lertaro.App)”">​</a></h3><ul><li><strong>Identity</strong>: Standard user-mode per-session WPF desktop application.</li><li><strong>Responsibilities</strong>: Hosts the centered Quick Search bar, Full Search window, Settings Center, global hotkey dispatching, action menus (<code>Ctrl+O</code>), and QuickLook preview panels.</li><li><strong>IPC Bridge &amp; CLI Hosting</strong>: Talks to the background service over the bidirectional named pipe <code>LertaroPipe</code> (<code>Core.Services.Search.SearchService</code> is the App-side client). It also hosts a dedicated per-user named pipe (<code>AppSearchPipeService</code>), allowing external tools like the <code>lff</code> CLI companion to reuse the App&#39;s initialized memory aliases, plugin providers, and cache trees without separate initialization.</li></ul><h3 id="_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook" tabindex="-1">3. Global Keyboard Hook &amp; Window Adapter Process (<code>Lertaro.Service --hook</code>) <a class="header-anchor" href="#_3-global-keyboard-hook-window-adapter-process-lertaro-service-hook" aria-label="Permalink to “3. Global Keyboard Hook &amp; Window Adapter Process (Lertaro.Service --hook)”">​</a></h3><ul><li><strong>Identity</strong>: Dedicated helper process started by the background service. It is launched <strong>elevated only when the signed-in account is a genuine administrator</strong>; otherwise it runs on the user&#39;s own token, so the bypass below is available on that machine only.</li><li><strong>Responsibilities</strong>: Hosts low-level global keyboard hooks and mouse activity listeners.</li><li><strong>UIPI Bypass &amp; Crash Isolation</strong>: Windows User Interface Privilege Isolation (UIPI) prohibits lower-integrity user applications from sending messages to elevated administrator windows. By hosting window adapters (<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code></a>) inside this process, Lertaro can read and drive administrator-run Explorers, Total Commander, and file dialogs when the hook was started elevated. Furthermore, anti-cheat hooks or crashes cannot bring down the main UI.</li></ul><h2 id="_2-shared-core-library-lertaro-core" tabindex="-1">2. Shared Core Library (<code>Lertaro.Core</code>) <a class="header-anchor" href="#_2-shared-core-library-lertaro-core" aria-label="Permalink to “2. Shared Core Library (Lertaro.Core)”">​</a></h2><p><code>Lertaro.Core</code> is referenced simultaneously by the Service, App, and Hook processes, containing:</p><ul><li><strong>fzf Fuzzy Matching Engine (<code>Core/SearchIndex/Fzf/*</code>)</strong>: Optimized character jump matching, substring scoring, and highlight masks, coupled with <code>SearchQueryParser</code> for drive letters and path tokens.</li><li><strong>Columnar In-Memory Index (<code>Core/IndexV2/*</code>)</strong>: High-performance memory-mapped columnar snapshots with an in-memory delta overlay for sub-millisecond searches across hundreds of millions of files.</li><li><strong>Binary IPC Protocols</strong>: Standard serialized message structures (<code>SearchRequestMessage</code>, binary serializers) enabling zero-copy inter-process communication.</li><li><strong>Multi-Process Logging (<code>Logger</code>)</strong>: Structured logging output to <code>service.log</code>, <code>app.log</code>, and <code>hook.log</code>, presented uniformly within the Settings live log viewer.</li></ul><h2 id="_3-plugin-architecture-lifecycle" tabindex="-1">3. Plugin Architecture &amp; Lifecycle <a class="header-anchor" href="#_3-plugin-architecture-lifecycle" aria-label="Permalink to “3. Plugin Architecture &amp; Lifecycle”">​</a></h2><p>All plugins are built on <code>Lertaro.PluginSdk</code> and dynamically loaded by <code>Lertaro.App</code>:</p><ul><li><strong>Zero-Privilege Direct Access</strong>: A plugin&#39;s own code runs in-process with whoever loaded it — normally the App, but see the next bullet for the two kinds the Service loads too. Nothing crosses a process boundary on its own account, so a plugin that needs custom directory indexing delegates the work through <code>DirectoryIndexerService</code> rather than walking the disk itself.</li><li><strong>Selective Dual-Loading</strong>: Search sources, actions and UI components run in the App process only. Three things are loaded into the other processes as well: window and file dialog adapters (<code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, <code>IInlineSearchAdapter</code>) go into the Hook process for cross-integrity window automation, and <code>IAliasProvider</code> plus <code>ITranslationProvider</code> are loaded by the <strong>Service</strong> too (<code>ServicePluginLoader</code>), because the indexer builds alias rows and needs the same transliteration and naming the UI shows.</li></ul>`,14)])}var d=i(l,[[`render`,u]]);export{c as __pageData,d as default};